declare @count int=0;
select @count = count(1) from ( select top 1 uid from dbo.[intersect] group by uid having count(1)>1 ) a
if (exists (select * from sys.indexes where name = 'IX_Intersect_Uid' and is_unique = 0) and @count = 0) begin if exists (select * from sys.indexes si where name = 'IX_Intersect_Uid' and object_name(object_id) = 'Intersect' and exists (select 1 from sys.objects so where so.object_id = si.object_id and schema_name(so.schema_id) = 'dbo')) begin drop INDEX [IX_Intersect_Uid] ON [dbo].[Intersect]; end if not exists (select * from sys.indexes where name = 'IX_Intersect_Uid') begin CREATE UNIQUE NONCLUSTERED INDEX [IX_Intersect_Uid] ON [dbo].[Intersect] ([uid] asc) end end

CREATE OR ALTER TRIGGER [dbo].[Intersect_AfterInsert] ON [dbo].[Intersect] FOR INSERT AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Add', [queue].WriteIndexXml('', I.Subject, I.SubjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Subject] = A.[Object] and I.[SubjectID] = a.[ObjectID];
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Add', [queue].WriteIndexXml('', I.Object, I.ObjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Object] = A.[Object] and I.[ObjectID] = a.[ObjectID]; END

CREATE OR ALTER TRIGGER [dbo].[Intersect_AfterUpdate] ON [dbo].[Intersect] FOR UPDATE AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Update', [queue].WriteIndexXml('', I.Subject, I.SubjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Subject] = A.[Object] and I.[SubjectID] = a.[ObjectID];
